 public static object Get(object o,string k){object v;return Obj(o).TryGetValue(k,out v)?v:null;}
 public static double RequiredTime(object o,string k){object v=Get(o,k);double n;if(v==null||v is bool||!double.TryParse(Convert.ToString(v,CultureInfo.InvariantCulture),NumberStyles.Float,CultureInfo.InvariantCulture,out n)||double.IsNaN(n)||double.IsInfinity(n))throw new Exception("服务返回了缺失或无效的时间，原始结果已保留。");return n;}
 public static string Str(object o,string k){return Convert.ToString(Get(o,k))??"";}
 public static double Num(object o,string k){double n;return double.TryParse(Convert.ToString(Get(o,k)),out n)?n:0;}
