 public static void Validate(Lesson p){if(p==null||p.cues==null||p.groups==null||p.peaks==null||string.IsNullOrWhiteSpace(p.audio)||double.IsNaN(p.duration)||double.IsInfinity(p.duration)||p.duration<=0)throw new Exception("材料数据不完整，请检查文件。");HashSet<string> ids=new HashSet<string>();foreach(Cue c in p.cues){if(c==null||string.IsNullOrEmpty(c.id)||!ids.Add(c.id)||double.IsNaN(c.start)||double.IsInfinity(c.start)||double.IsNaN(c.end)||double.IsInfinity(c.end)||c.start<0||c.end<=c.start||c.end>p.duration+.001)throw new Exception("片段时间或编号无效，未保存覆盖原材料。请检查修改。");}HashSet<string> assigned=new HashSet<string>();foreach(Group g in p.groups){if(g==null||g.takes==null)throw new Exception("分组数据不完整。");foreach(Take t in g.takes){if(t==null||t.cues==null)throw new Exception("遍次数据不完整。");foreach(string id in t.cues)if(!ids.Contains(id)||!assigned.Add(id))throw new Exception("片段归组缺失或重复，请重新分组。");}}if(ids.Count!=assigned.Count)throw new Exception("有片段未归组，请先重新分组。");if(p.peaks.Count>0&&(p.peakStep<=0||double.IsNaN(p.peakStep)||double.IsInfinity(p.peakStep)))throw new Exception("波形时间单位无效。");}
 public static void SaveLesson(string file,Lesson p){Validate(p);Save(file,p);StringBuilder b=new StringBuilder();int i=0;foreach(Cue c in p.cues.OrderBy(x=>x.start)){b.Append(++i).Append("\r\n").Append(Stamp(c.start)).Append(" --> ").Append(Stamp(c.end)).Append("\r\n").Append(c.text).Append("\r\n\r\n");}string srt=Path.Combine(Path.GetDirectoryName(file),"听力字幕.srt");string temp=srt+".tmp";File.WriteAllText(temp,b.ToString(),new UTF8Encoding(true));if(File.Exists(srt))File.Replace(temp,srt,srt+".bak",true);else File.Move(temp,srt);}
 public static int ChineseNumber(string s){int n;if(int.TryParse(s,out n))return n;string ds="零一二三四五六七八九";if(s=="两")return 2;if(s.Contains("十")){string[] v=s.Split('十');return (v[0]==""?1:ds.IndexOf(v[0][0]))*10+(v.Length>1&&v[1]!=""?ds.IndexOf(v[1][0]):0);}return s.Length==1?ds.IndexOf(s[0]):-1;}
 public static bool Instruction(Cue c){return CueClassifier.Instruction(c.text);}
 public static string Norm(string s){return Regex.Replace(s.ToLowerInvariant(),@"[^a-z0-9\u4e00-\u9fff]","");}
 public static List<Cue> ParseRaw(object raw,double duration){List<Cue> a=new List<Cue>();object sentences;
  if(Get(raw,"transcripts")!=null){sentences=Arr(Get(raw,"transcripts")).SelectMany(t=>Arr(Get(t,"sentences"))).ToArray();}
  else {object r=Get(raw,"result")??raw;sentences=Get(r,"utterances");}
  int i=0;foreach(object s in Arr(sentences)){string text=Str(s,"text").Trim();if(text=="")continue;bool ali=Get(s,"begin_time")!=null;double start=RequiredTime(s,ali?"begin_time":"start_time")/1000,end=RequiredTime(s,"end_time")/1000;
   if(Get(s,ali?"begin_time":"start_time")==null||Get(s,"end_time")==null||double.IsNaN(start)||double.IsInfinity(start)||double.IsNaN(end)||double.IsInfinity(end)||start<0||end<=start||duration>0&&start>=duration)throw new Exception("服务返回了缺失或越界的句子时间，原始结果已保留，请检查。");
   Cue c=new Cue{id="c"+(++i),text=text,start=Math.Max(0,start),end=end};
   foreach(object w in Arr(Get(s,"words"))){double ws=Num(w,Get(w,"begin_time")!=null?"begin_time":"start_time")/1000,we=Num(w,"end_time")/1000;string wt=Str(w,"text")+Str(w,"punctuation");if(ws>=0&&we>ws&&!string.IsNullOrWhiteSpace(wt)&&ws>=start-.1&&we<=end+.1)c.words.Add(new Word{start=ws,end=we,text=wt});}
   if(duration>0 && c.end>duration){c.note="服务时间超出音频末尾，请核对";c.end=duration;}
   a.Add(c);
  }if(a.Count==0)throw new Exception("识别没有返回带时间的句子，不能自动生成有效材料。");return a.OrderBy(c=>c.start).ToList();
 }
 public static int SmoothFragments(Lesson p){int count=0;for(int i=0;i+1<p.cues.Count;i++){Cue a=p.cues[i],b=p.cues[i+1];if(b.start-a.end>.40||Instruction(a)||Instruction(b))continue;bool abbreviation=Regex.IsMatch(a.text,@"\b[ap]\.$",RegexOptions.IgnoreCase)&&Regex.IsMatch(b.text.Trim(),@"^m\.$",RegexOptions.IgnoreCase);bool tail=Regex.IsMatch(a.text,@"\b[ap]\.m\.$",RegexOptions.IgnoreCase)&&b.text.Trim().Equals("now.",StringComparison.OrdinalIgnoreCase);if(!abbreviation&&!tail)continue;a.text=abbreviation?a.text.TrimEnd()+b.text.Trim():a.text.TrimEnd()+" "+b.text.Trim();a.end=Math.Max(a.end,b.end);a.words.AddRange(b.words);foreach(Group g in p.groups)foreach(Take t in g.takes)t.cues.Remove(b.id);p.cues.RemoveAt(i+1);count++;i--;}return count;}
 public static void GroupCues(Lesson p){p.groups.Clear();foreach(Cue c in p.cues)if(CueClassifier.NeedsReview(c.text)&&!c.note.Contains("归组待确认"))c.note+=(c.note.Length>0?" ":"")+"归组待确认："+CueClassifier.ReviewReason(c.text);
  List<int> markers=Enumerable.Range(0,p.cues.Count).Where(i=>CueClassifier.StartsNewMaterial(p.cues[i].text)).ToList();HashSet<string> assigned=new HashSet<string>();
  foreach(int marker in markers){int next=markers.FirstOrDefault(x=>x>marker);if(next==0)next=p.cues.Count;Cue prompt=p.cues[marker];bool numbered;string label=GroupingRules.Label(prompt.text,p.groups.Count+1,out numbered);
   List<Cue> body=p.cues.Skip(marker+1).Take(next-marker-1).TakeWhile(c=>!CueClassifier.NeedsReview(c.text)).Where(c=>!Instruction(c)).ToList();if(body.Count==0)continue;Group g=new Group{title=label,confirmed=numbered};int repeat=GroupingRules.FindRepeat(body);
   if(repeat>0){g.takes.Add(new Take{title="第一遍",cues=body.Take(repeat).Select(c=>c.id).ToList()});g.takes.Add(new Take{title="第二遍",cues=body.Skip(repeat).Select(c=>c.id).ToList()});}else g.takes.Add(new Take{title="原录音",cues=body.Select(c=>c.id).ToList()});foreach(Cue c in body)assigned.Add(c.id);p.groups.Add(g);
  }
  if(p.groups.Count==0){List<Cue> body=p.cues.Where(c=>!Instruction(c)&&!CueClassifier.NeedsReview(c.text)).ToList();Group g=null;double last=-100;foreach(Cue c in body){if(g==null||c.start-last>8){g=new Group{title="材料 "+(p.groups.Count+1)+"（请确认分组）"};g.takes.Add(new Take{title="原录音"});p.groups.Add(g);}g.takes[0].cues.Add(c.id);assigned.Add(c.id);last=c.end;}}
  List<Cue> rest=p.cues.Where(c=>!assigned.Contains(c.id)).ToList();List<string> prompts=rest.Where(Instruction).Select(c=>c.id).ToList();if(prompts.Count>0)p.groups.Add(new Group{title="考试提示语",takes=new List<Take>{new Take{title="提示语",cues=prompts}}});List<string> pending=rest.Where(c=>!Instruction(c)).Select(c=>c.id).ToList();if(pending.Count>0)p.groups.Add(new Group{title="待确认材料（未自动归题）",takes=new List<Take>{new Take{title="请核对",cues=pending}}});
 }
 public static void Pad(Lesson p){for(int i=0;i<p.cues.Count;i++){Cue c=p.cues[i];double before=i>0?p.cues[i-1].end:0,after=i+1<p.cues.Count?p.cues[i+1].start:p.duration;c.start=Math.Max(Math.Max(0,c.start-.10),Math.Min(c.start,before));c.end=Math.Min(Math.Min(p.duration,c.end+.12),Math.Max(c.end,after));}}
 public static void Wave(string ffmpeg,string audio,string pcm,Lesson p,Action<string> progress){
  progress("正在生成可编辑波形…");Directory.CreateDirectory(Path.GetDirectoryName(pcm));FileInfo src=new FileInfo(audio);string signature=src.Length+"|"+src.LastWriteTimeUtc.Ticks;string marker=pcm+".complete";
  bool complete=File.Exists(pcm)&&new FileInfo(pcm).Length>0&&new FileInfo(pcm).Length%2==0&&File.Exists(marker)&&File.ReadAllText(marker)==signature+"|"+new FileInfo(pcm).Length;
  if(!complete){if(!File.Exists(ffmpeg))throw new Exception("请先将ffmpeg.exe放到家里处理器的工具文件夹；操作步骤见首次配置说明。");string temp=pcm+".building-"+Guid.NewGuid().ToString("N");ProcessStartInfo info=new ProcessStartInfo(ffmpeg,"-hide_banner -loglevel error -y -i \""+audio+"\" -vn -ac 1 -ar 16000 -f s16le \""+temp+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true};
   using(Process proc=Process.Start(info)){string error=proc.StandardError.ReadToEnd();proc.WaitForExit();if(proc.ExitCode!=0||!File.Exists(temp)||new FileInfo(temp).Length==0||new FileInfo(temp).Length%2!=0)throw new Exception("音频解码未完成，请重试："+error);}
   if(File.Exists(pcm))File.Replace(temp,pcm,pcm+".bak",true);else File.Move(temp,pcm);File.WriteAllText(marker,signature+"|"+new FileInfo(pcm).Length);
  }
  List<int> peaks=new List<int>();long samples=0;using(BinaryReader r=new BinaryReader(File.OpenRead(pcm))){while(r.BaseStream.Position<r.BaseStream.Length){int peak=0;for(int i=0;i<800&&r.BaseStream.Position+1<r.BaseStream.Length;i++){peak=Math.Max(peak,Math.Abs((int)r.ReadInt16()));samples++;}peaks.Add(peak);}}p.peaks=peaks;p.duration=samples/16000.0;p.peakStep=.05;
 }
 public static List<Cue> SilenceCues(Lesson p){if(p.peaks.Count==0)throw new Exception("没有可分析的声音数据，请重新载入音频。");List<Cue> cues=new List<Cue>();double start=-1,lastVoice=0;int threshold=Math.Max(450,p.peaks.OrderBy(x=>x).ElementAt(Math.Max(0,p.peaks.Count/5))*3);for(int i=0;i<p.peaks.Count;i++){double t=i*p.peakStep;if(p.peaks[i]>threshold){if(start<0)start=t;lastVoice=t;}if(start>=0&&(t-lastVoice>.55||i==p.peaks.Count-1)){if(lastVoice-start>=.10)cues.Add(new Cue{id="s"+cues.Count,start=Math.Max(0,start-.12),end=Math.Min(p.duration,lastVoice+.20),text="片段 "+(cues.Count+1)+"（未生成字幕）",note="按声音停顿切分，请试听"});start=-1;}}if(cues.Count==0)throw new Exception("未检测到可用的语音片段，请检查录音或改用语音识别。");return cues;}
}

public class ClipProvider : IWaveProvider {
 IWaveProvider source;long left;
 public ClipProvider(IWaveProvider r,double seconds){source=r;left=(long)(seconds*r.WaveFormat.AverageBytesPerSecond);left-=left%r.WaveFormat.BlockAlign;}
 public WaveFormat WaveFormat{get{return source.WaveFormat;}}
 public int Read(byte[] b,int offset,int count){int n=(int)Math.Min(count,left);n-=n%WaveFormat.BlockAlign;if(n<=0)return 0;int read=source.Read(b,offset,n);left-=read;return read;}
}
public class Audio : IDisposable {
 WaveStream reader;SampleChannel channel;WaveOutEvent output;double begin=0;float volume=1;public double end=0;public bool active=false;
 public void Open(string path){WaveStream next=Path.GetExtension(path).Equals(".mp3",StringComparison.OrdinalIgnoreCase)?(WaveStream)new Mp3FileReader(path):new AudioFileReader(path);SampleChannel nextChannel;try{nextChannel=new SampleChannel(next,false);nextChannel.Volume=volume;}catch{next.Dispose();throw;}Dispose();reader=next;channel=nextChannel;}
 public double Length{get{return reader==null?0:reader.TotalTime.TotalSeconds;}}
 public double Position{get{return output==null?begin:Math.Min(end,begin+output.GetPosition()/(double)(channel.WaveFormat.SampleRate*channel.WaveFormat.Channels*2));}}
 public bool Playing{get{return output!=null&&output.PlaybackState==PlaybackState.Playing;}}
 public int Plays{get;private set;}
 public void Play(double s,double e){if(reader==null)return;Stop();if(output!=null){output.Dispose();output=null;}begin=Math.Max(0,Math.Min(s,Length));end=Math.Max(begin,Math.Min(e,Length));reader.CurrentTime=TimeSpan.FromSeconds(begin);output=new WaveOutEvent{DesiredLatency=240,NumberOfBuffers=3};output.Init(new ClipProvider(new SampleToWaveProvider16(channel),end-begin));output.Play();active=true;Plays++;}
 public void Stop(){if(output!=null)output.Stop();active=false;}
 public void Volume(int v){volume=Math.Max(0,Math.Min(1000,v))/1000f;if(channel!=null)channel.Volume=volume;}
 // This version plays at normal speed; no unused speed controls.
 public void Dispose(){if(output!=null){output.Stop();output.Dispose();output=null;}if(reader!=null){reader.Dispose();reader=null;}active=false;}
}

public class UploadContent : HttpContent {
 byte[] prefix,suffix;string file;
 public UploadContent(Dictionary<string,string> fields,string path,string transport){file=path;string boundary="----Listening"+Guid.NewGuid().ToString("N");StringBuilder b=new StringBuilder();foreach(var f in fields)b.Append("--").Append(boundary).Append("\r\nContent-Disposition: form-data; name=\"").Append(f.Key).Append("\"\r\n\r\n").Append(f.Value).Append("\r\n");b.Append("--").Append(boundary).Append("\r\nContent-Disposition: form-data; name=\"file\"; filename=\"").Append(transport).Append("\"\r\nContent-Type: application/octet-stream\r\n\r\n");prefix=Encoding.UTF8.GetBytes(b.ToString());suffix=Encoding.ASCII.GetBytes("\r\n--"+boundary+"--\r\n");Headers.TryAddWithoutValidation("Content-Type","multipart/form-data; boundary="+boundary);}
 protected override bool TryComputeLength(out long length){length=prefix.LongLength+new FileInfo(file).Length+suffix.LongLength;return true;}
 protected override async Task SerializeToStreamAsync(Stream stream,TransportContext context){await stream.WriteAsync(prefix,0,prefix.Length);using(FileStream f=File.OpenRead(file))await f.CopyToAsync(stream);await stream.WriteAsync(suffix,0,suffix.Length);}
}
public class Clouds {
 static HttpClient client;public static HttpClient Http{get{if(client==null){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;client=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false});client.Timeout=TimeSpan.FromMinutes(8);}return client;}}
 static async Task<object> Send(string url,string key,object body,Dictionary<string,string> extra,bool ali){using(HttpRequestMessage r=new HttpRequestMessage(body==null?HttpMethod.Get:HttpMethod.Post,url)){if(key!="")r.Headers.TryAddWithoutValidation(ali?"Authorization":"X-Api-Key",ali?"Bearer "+key:key);if(extra!=null)foreach(var x in extra)r.Headers.TryAddWithoutValidation(x.Key,x.Value);if(body!=null)r.Content=new StringContent(Data.Dump(body),Encoding.UTF8,"application/json");using(HttpResponseMessage response=await Http.SendAsync(r)){string text=await response.Content.ReadAsStringAsync();if(!response.IsSuccessStatusCode){if(!ali&&(int)response.StatusCode==403&&text.Contains("requested resource not granted"))throw new Exception("豆包语音未授权录音文件极速版（volc.bigasr.auc_turbo）。请到开通管理核对服务和Key所属项目：https://console.volcengine.com/speech/new/setting/activate");string clean=text.Replace(key==""?"__not_key__":key,"[密钥隐藏]");throw new Exception("云服务 HTTP "+(int)response.StatusCode+"："+clean.Substring(0,Math.Min(clean.Length,600)));}IEnumerable<string> status;if(!ali&&response.Headers.TryGetValues("X-Api-Status-Code",out status)&&status.First()!="20000000")throw new Exception("豆包未完成识别："+string.Join(" ",status)+"。请核对是否开通文件极速识别。");return Data.Json().DeserializeObject(text);}}}
 public static async Task<object> Doubao(string audio,string key,string language,Action<string> status,string model="bigmodel",string resource="volc.bigasr.auc_turbo"){if(key=="")throw new Exception("请在“识别设置”填写豆包语音 API Key。");if(new FileInfo(audio).Length>95000000)throw new Exception("豆包直传版单文件须小于100MB。");status("正在上传到豆包并识别，请稍候…");var a=new Dictionary<string,object>{{"data",Convert.ToBase64String(File.ReadAllBytes(audio))}};if(language!="")a["language"]=language=="en"?"en-US":"zh-CN";object body=new Dictionary<string,object>{{"user",new {uid="listening-studio"}},{"audio",a},{"request",new {model_name=model,show_utterances=true,enable_punc=true,enable_itn=false,enable_ddc=false}}};return await Send("https://openspeech.bytedance.com/api/v3/auc/bigmodel/recognize/flash",key,body,new Dictionary<string,string>{{"X-Api-Resource-Id",resource},{"X-Api-Request-Id",Guid.NewGuid().ToString()},{"X-Api-Sequence","-1"}},false);}
 public static string TaskState(object output){string state=Data.Str(output,"task_status");if(string.IsNullOrWhiteSpace(state))throw new Exception("本次查询缺少任务状态，任务编号及恢复记录已保留。任务可能仍在云端运行，请继续查询或先到控制台核对，勿重复提交。");return state;}
 public static async Task<object> Alibaba(string audio,string key,string language,string jobFile,Action<string> status,string model="qwen3-asr-flash-filetrans"){if(key=="")throw new Exception("请在“识别设置”填写阿里百炼 API Key。");const string baseUrl="https://dashscope.aliyuncs.com";string task="";if(File.Exists(jobFile))task=Data.Str(Data.Json().DeserializeObject(File.ReadAllText(jobFile)),"task_id");
  if(task==""){status("正在取得上传凭证…");object policyResponse=await Send(baseUrl+"/api/v1/uploads?action=getPolicy&model="+Uri.EscapeDataString(model)+"",key,null,null,true);object p=Data.Get(policyResponse,"data");string transport="audio"+Path.GetExtension(audio);string objectKey=Data.Str(p,"upload_dir").TrimEnd('/')+"/"+Guid.NewGuid().ToString("N")+"_"+transport;
   var fields=new Dictionary<string,string>{{"OSSAccessKeyId",Data.Str(p,"oss_access_key_id")},{"policy",Data.Str(p,"policy")},{"Signature",Data.Str(p,"signature")},{"key",objectKey},{"success_action_status","200"}};foreach(var pair in new[]{new[]{"x_oss_object_acl","x-oss-object-acl"},new[]{"x_oss_forbid_overwrite","x-oss-forbid-overwrite"}})if(Data.Str(p,pair[0])!="")fields[pair[1]]=Data.Str(p,pair[0]);
   using(UploadContent form=new UploadContent(fields,audio,transport)){status("正在上传完整音频…");using(var res=await Http.PostAsync(Data.Str(p,"upload_host"),form)){if(!res.IsSuccessStatusCode)throw new Exception("音频上传失败 HTTP "+(int)res.StatusCode+"。未提交识别。");}}
   var pars=new Dictionary<string,object>{{"enable_words",true},{"enable_itn",false}};if(language!="")pars["language"]=language;
   object submitted=await Send(baseUrl+"/api/v1/services/audio/asr/transcription",key,new Dictionary<string,object>{{"model",model},{"input",new{file_url="oss://"+objectKey}},{"parameters",pars}},new Dictionary<string,string>{{"X-DashScope-Async","enable"},{"X-DashScope-OssResourceResolve","enable"}},true);
   task=Data.Str(Data.Get(submitted,"output"),"task_id");if(task=="")throw new Exception("未取得任务编号，请先检查云端记录再重试。");Data.Save(jobFile,new{task_id=task});File.WriteAllText(Path.Combine(Path.GetDirectoryName(jobFile),"恢复云任务.txt"),Path.GetFileName(jobFile));
  }
  DateTime deadline=DateTime.UtcNow.AddHours(1);while(DateTime.UtcNow<deadline){status("正在等待云端转写（已有任务不会重复提交）…");object r=await Send(baseUrl+"/api/v1/tasks/"+Uri.EscapeDataString(task),key,null,null,true);object o=Data.Get(r,"output");string state=TaskState(o);if(state=="SUCCEEDED"){object result=Data.Get(o,"result")??Data.Arr(Data.Get(o,"results")).FirstOrDefault();string url=Data.Str(result,"transcription_url");if(url.StartsWith("http://"))url="https://"+url.Substring(7);if(!url.StartsWith("https://"))throw new Exception("云端结果地址无效，任务编号已保存。");return await Send(url,"",null,null,true);}if(state=="FAILED"||state=="UNKNOWN"){Data.Save(jobFile,new{task_id=task,task_status=state});string marker=Path.Combine(Path.GetDirectoryName(jobFile),"恢复云任务.txt");if(File.Exists(marker)&&Path.GetFileName(File.ReadAllText(marker))==Path.GetFileName(jobFile))File.Delete(marker);throw new Exception("云端任务失败："+Data.Str(o,"code")+" "+Data.Str(o,"message"));}await Task.Delay(3000);}throw new Exception("等待超时，稍后重试将继续查询原任务。");
 }
}

public class WaveView : Control {
 public Lesson Lesson;public Cue Cue;public double Playhead,From,To=10;public bool Editable=true;public event Action DragStarted;public event Action<double,double> BoundaryChanged;public event Action<double> Seek;int dragging=0;
 public WaveView(){DoubleBuffered=true;BackColor=Color.FromArgb(241,245,249);Height=160;SetStyle(ControlStyles.ResizeRedraw,true);}
 public void FocusCue(Cue c){Cue=c;if(c!=null){From=Math.Max(0,c.start-2);To=Math.Min(Lesson.duration,Math.Max(c.end+2,From+6));}Invalidate();}
 float X(double t){return (float)((t-From)/Math.Max(.1,To-From)*Width);}
 double T(int x){return Math.Max(0,Math.Min(Lesson==null?0:Lesson.duration,From+(To-From)*x/Math.Max(1,Width)));}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);Graphics g=e.Graphics;g.SmoothingMode=SmoothingMode.None;g.DrawLine(Pens.LightGray,0,Height/2,Width,Height/2);if(Lesson==null)return;
  if(Cue!=null){using(Brush b=new SolidBrush(Color.FromArgb(50,37,99,235)))g.FillRectangle(b,X(Cue.start),0,X(Cue.end)-X(Cue.start),Height-24);}
  if(Lesson.peaks.Count>0){using(Pen p=new Pen(Color.FromArgb(30,110,150))){for(int x=0;x<Width;x++){int a=Math.Max(0,(int)(T(x)/Lesson.peakStep)),b=Math.Min(Lesson.peaks.Count-1,(int)(T(x+1)/Lesson.peakStep));int peak=0;for(int j=a;j<=b&&j<Lesson.peaks.Count;j++)peak=Math.Max(peak,Lesson.peaks[j]);float h=peak/32768f*(Height-32)/2;g.DrawLine(p,x,(Height-24)/2-h,x,(Height-24)/2+h);}}}
  if(Cue!=null){using(Pen p=new Pen(Color.RoyalBlue,3)){g.DrawLine(p,X(Cue.start),0,X(Cue.start),Height-24);g.DrawLine(p,X(Cue.end),0,X(Cue.end),Height-24);}g.DrawString("起点",Font,Brushes.RoyalBlue,X(Cue.start)+3,2);g.DrawString("终点",Font,Brushes.RoyalBlue,X(Cue.end)-32,2);}
  g.DrawLine(Pens.OrangeRed,X(Playhead),0,X(Playhead),Height-24);g.DrawString(Data.Time(From),Font,Brushes.DimGray,3,Height-22);string end=Data.Time(To);g.DrawString(end,Font,Brushes.DimGray,Math.Max(0,Width-100),Height-22);
 }
 protected override void OnMouseDown(MouseEventArgs e){if(Lesson==null)return;if(Editable&&Cue!=null&&Math.Abs(e.X-X(Cue.start))<12)dragging=1;else if(Editable&&Cue!=null&&Math.Abs(e.X-X(Cue.end))<12)dragging=2;else{Playhead=T(e.X);if(Seek!=null)Seek(Playhead);Invalidate();}if(dragging!=0&&DragStarted!=null)DragStarted();}
 protected override void OnMouseMove(MouseEventArgs e){if(dragging==0||Cue==null)return;double t=T(e.X);if(dragging==1)Cue.start=Math.Min(t,Cue.end-.05);else Cue.end=Math.Max(t,Cue.start+.05);Invalidate();}
 protected override void OnMouseUp(MouseEventArgs e){if(dragging!=0&&Cue!=null&&BoundaryChanged!=null)BoundaryChanged(Cue.start,Cue.end);dragging=0;}
}

