  foreach(string folder in Directory.GetDirectories(library,"*",SearchOption.AllDirectories).OrderByDescending(f=>File.Exists(Path.Combine(f,"lesson.json"))?File.GetLastWriteTimeUtc(Path.Combine(f,"lesson.json")):Directory.GetLastWriteTimeUtc(f))){string projectFile=Path.Combine(folder,"lesson.json");try{Lesson ready=File.Exists(projectFile)?Data.Load<Lesson>(projectFile):null;string[] candidates;if(ready!=null)candidates=new[]{Data.AudioPath(projectFile,ready)};else{if(!File.Exists(Path.Combine(folder,"恢复云任务.txt"))&&Directory.GetFiles(folder,"*.upload.json").Length==0&&Directory.GetFiles(folder,"*.result.json").Length==0)continue;candidates=Directory.GetFiles(folder).Where(f=>new[]{".mp3",".wav",".m4a",".flac",".ogg",".aac"}.Contains(Path.GetExtension(f).ToLowerInvariant())).ToArray();}
   foreach(string audioFile in candidates){if(!File.Exists(audioFile)||new FileInfo(audioFile).Length!=sourceLength)continue;if(sourceHash==null)sourceHash=Fingerprint(source);if(Fingerprint(audioFile)!=sourceHash)continue;if(ready==null){using(Audio reader=new Audio()){reader.Open(audioFile);ready=new Lesson{title=Path.GetFileNameWithoutExtension(audioFile),audio=Path.GetFileName(audioFile),duration=reader.Length};}Data.SaveLesson(projectFile,ready);}Data.Validate(ready);return projectFile;}
  }catch{}}return null;
 }
 public void OpenAudioFile(string source,string libraryOverride=null){if(libraryOverride==null){string prepared=FindPreparedProject(source);if(prepared!=null){LoadProject(prepared);Status(lesson.cues.Count==0?"已打开未完成材料。点击自动处理可恢复原任务，不另建材料。":"已打开本机已有结果，没有上传或识别。需要新结果请点重新识别；修分句可点本地优化。");return;}}string library=libraryOverride??Path.GetFullPath(Path.Combine(home,"..","材料"));Directory.CreateDirectory(library);string folder=Path.Combine(library,Data.SafeName(Path.GetFileNameWithoutExtension(source))+"_"+DateTime.Now.ToString("MMddHHmmss")+"_"+Guid.NewGuid().ToString("N").Substring(0,4));Directory.CreateDirectory(folder);string dest=Path.Combine(folder,Path.GetFileName(source));File.Copy(source,dest);audio.Open(dest);ResetState();lesson=new Lesson{title=Path.GetFileNameWithoutExtension(dest),audio=Path.GetFileName(dest),duration=audio.Length};project=Path.Combine(folder,"lesson.json");Data.SaveLesson(project,lesson);title.Text=lesson.title;wave.Lesson=lesson;wave.Cue=null;wave.Playhead=0;wave.From=0;wave.To=Math.Min(20,lesson.duration);loading=true;tree.Nodes.Clear();grid.Rows.Clear();loading=false;dirty=false;welcome.Visible=true;RefreshSubtitle();subtitle.Text=EditionConfig.Internal(home)?"授权已配置，下一步：点击自动处理":"下一步：添加模型 / API Key → 自动处理";UpdateServiceInfo();Status("仅载入了完整音频，尚未生成字幕和分段。请点击上方或中间的自动处理。");}
