 void MergeCue(){StopPlayback();int i=Index;if(i<0||i+1>=visible.Count)return;Snapshot();Cue a=visible[i],b=visible[i+1];a.start=Math.Min(a.start,b.start);a.end=Math.Max(a.end,b.end);a.text=a.text.Trim()+" "+b.text.Trim();a.words.AddRange(b.words);lesson.cues.Remove(b);foreach(Group g in lesson.groups)foreach(Take t in g.takes)t.cues.Remove(b.id);Changed();SelectTree(tree.SelectedNode);SelectCueById(a.id);}
 void SplitCue(){StopPlayback();Cue c=Current;if(c==null)return;double cut=pending;if(cut<=c.start+.08||cut>=c.end-.08)cut=(c.start+c.end)/2;Snapshot();string left="",right="";var lw=c.words.Where(w=>(w.start+w.end)/2<cut).ToList();var rw=c.words.Where(w=>(w.start+w.end)/2>=cut).ToList();if(lw.Count>0&&rw.Count>0&&string.Equals(Regex.Replace(string.Join(" ",c.words.Select(w=>w.text)).Trim(),@"\s+"," "),Regex.Replace(c.text.Trim(),@"\s+"," "),StringComparison.Ordinal)){left=string.Join(" ",lw.Select(w=>w.text));right=string.Join(" ",rw.Select(w=>w.text));}else{string[] words=c.text.Split(' ');int k=Math.Max(1,words.Length/2);left=string.Join(" ",words.Take(k));right=string.Join(" ",words.Skip(k));if(right=="")right="（请补充本段文字）";}
  Cue second=new Cue{id=Guid.NewGuid().ToString("N"),start=cut,end=c.end,text=right,words=rw,note="手动拆分，请核对文字"};c.end=cut;c.text=left;c.words=lw;lesson.cues.Insert(lesson.cues.IndexOf(c)+1,second);foreach(Group g in lesson.groups)foreach(Take t in g.takes){int k=t.cues.IndexOf(c.id);if(k>=0)t.cues.Insert(k+1,second.id);}Changed();SelectTree(tree.SelectedNode);SelectCueById(c.id);}
 void Undo(){if(undo.Count==0)return;StopPlayback();string id=undoSelection.Count>0?undoSelection.Pop():"";lesson=Data.Json().Deserialize<Lesson>(undo.Pop());wave.Lesson=lesson;Changed();BuildTree();SelectCueById(id);}
 void EditGroup(){if(selectedGroup==null||selectedTake==null||visible.Count==0)return;StopPlayback();Group targetGroup=selectedGroup;Take targetTake=selectedTake;using(Form f=new Form{Text="材料名称与分组范围",Size=new Size(620,310),StartPosition=FormStartPosition.CenterParent,Font=Font}){TableLayoutPanel panel=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),ColumnCount=2};panel.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,110));panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));f.Controls.Add(panel);TextBox box=new TextBox{Text=targetGroup.title,Dock=DockStyle.Fill};panel.Controls.Add(new Label{Text="材料名称",AutoSize=true},0,0);panel.Controls.Add(box,1,0);CheckBox adjust=new CheckBox{Text="同时调整当前遍次的句子范围",AutoSize=true};panel.Controls.Add(adjust,0,1);panel.SetColumnSpan(adjust,2);NumericUpDown a=new NumericUpDown{DecimalPlaces=2,Maximum=(decimal)lesson.duration,Value=(decimal)visible.First().start,Width=150},b=new NumericUpDown{DecimalPlaces=2,Maximum=(decimal)lesson.duration,Value=(decimal)visible.Last().end,Width=150};panel.Controls.Add(new Label{Text="开始（秒）",AutoSize=true},0,2);panel.Controls.Add(a,1,2);panel.Controls.Add(new Label{Text="结束（秒）",AutoSize=true},0,3);panel.Controls.Add(b,1,3);Label hint=new Label{Text="按句子中点归组，原音频不裁剪。移出本组且未归属其他材料的句子会放入“待整理片段”。",AutoSize=true,MaximumSize=new Size(560,60)};panel.Controls.Add(hint,0,4);panel.SetColumnSpan(hint,2);Button ok=new Button{Text="应用",AutoSize=true};panel.Controls.Add(ok,1,5);ok.Click+=(s,e)=>{if(b.Value<=a.Value){MessageBox.Show("结束时间应晚于开始时间。");return;}Snapshot();targetGroup.title=box.Text;targetGroup.confirmed=true;if(adjust.Checked){List<string> ids=lesson.cues.Where(c=>!Data.Instruction(c)&&(c.start+c.end)/2>=(double)a.Value&&(c.start+c.end)/2<=(double)b.Value).Select(c=>c.id).ToList();foreach(Group g in lesson.groups)foreach(Take t in g.takes)if(t!=targetTake)t.cues.RemoveAll(id=>ids.Contains(id));targetTake.cues=ids;HashSet<string> assigned=new HashSet<string>(lesson.groups.SelectMany(g=>g.takes).SelectMany(t=>t.cues));List<string> remaining=lesson.cues.Where(c=>!assigned.Contains(c.id)).Select(c=>c.id).ToList();if(remaining.Count>0)lesson.groups.Add(new Group{title="待整理片段",takes=new List<Take>{new Take{title="请确认归组",cues=remaining}}});foreach(Group g in lesson.groups)g.takes.RemoveAll(t=>t.cues.Count==0);lesson.groups.RemoveAll(g=>g.takes.Count==0);}Changed();f.DialogResult=DialogResult.OK;};if(f.ShowDialog(this)==DialogResult.OK)BuildTree();}}
 void Zoom(double factor){if(lesson==null)return;double center=Current==null?pending:(Current.start+Current.end)/2;double span=Math.Max(2,Math.Min(lesson.duration,(wave.To-wave.From)*factor));wave.From=Math.Max(0,center-span/2);wave.To=Math.Min(lesson.duration,wave.From+span);wave.Invalidate();}
 public string ExportTo(string parent){if(lesson==null||lesson.cues.Count==0)throw new Exception("请先完成自动处理。");Save();string folder=Path.Combine(parent,Data.SafeName(lesson.title)+"_课堂_"+DateTime.Now.ToString("MMddHHmmss")+"_"+Guid.NewGuid().ToString("N").Substring(0,4));Directory.CreateDirectory(folder);File.Copy(Data.AudioPath(project,lesson),Path.Combine(folder,lesson.audio));Data.SaveLesson(Path.Combine(folder,"lesson.json"),lesson);File.Copy(typeof(Studio).Assembly.Location,Path.Combine(folder,"课堂播放器.exe"));foreach(string dll in Directory.GetFiles(home,"NAudio*.dll"))File.Copy(dll,Path.Combine(folder,Path.GetFileName(dll)));string updateHelper=Path.Combine(home,"更新助手.exe");if(File.Exists(updateHelper))File.Copy(updateHelper,Path.Combine(folder,"更新助手.exe"));string license=Path.Combine(home,"开源许可.txt");if(File.Exists(license))File.Copy(license,Path.Combine(folder,"开源许可.txt"));File.WriteAllText(Path.Combine(folder,"打开说明.txt"),"双击课堂播放器.exe，自动读取本目录材料。整文件夹复制到学校即可，包含一个完整音频和小型时间轴。字幕可隐藏，点击句子重听。\r\n长对话多题共享同一材料，按题号范围显示。",Encoding.UTF8);Status("已导出："+folder);return folder;}
 void Export(){if(lesson==null||lesson.cues.Count==0)throw new Exception("请先完成自动处理。");using(FolderBrowserDialog d=new FolderBrowserDialog{Description="选择 U 盘或 F 盘的课堂材料保存位置",SelectedPath=Path.GetFullPath(Path.Combine(home,".."))}){if(d.ShowDialog()!=DialogResult.OK)return;string folder=ExportTo(d.SelectedPath);MessageBox.Show("已导出完整课堂材料。把整个文件夹带到学校，双击课堂播放器.exe。\r\n"+folder);}}
}

public static class Program {
 public static bool TryLoadStartup(Studio f,string file,Action<string> report){try{f.LoadProject(file);return true;}catch(Exception ex){report(ex.Message+"\r\n请使用“打开课堂材料”或“打开音频 / 材料”选择完整的材料文件夹。");return false;}}
 [STAThread]public static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.ThreadException+=(s,e)=>MessageBox.Show(e.Exception.Message,"操作未完成");try{
  if(args.Length>0&&args[0]=="--prepare"){string audio=args[1],raw=args[2],folder=args[3],ffmpeg=args[4];Directory.CreateDirectory(folder);string dest=Path.Combine(folder,Path.GetFileName(audio));if(!File.Exists(dest))File.Copy(audio,dest);Lesson p=new Lesson{title=Path.GetFileNameWithoutExtension(audio),audio=Path.GetFileName(audio),provider="阿里千问（已完成任务取回）"};Data.Wave(ffmpeg,dest,Path.Combine(folder,"缓存","完整音频.pcm"),p,s=>Console.WriteLine(s));p.cues=Data.ParseRaw(Data.Json().DeserializeObject(File.ReadAllText(raw,Encoding.UTF8)),p.duration);Data.Pad(p);Data.GroupCues(p);File.Copy(raw,Path.Combine(folder,"识别原始结果.json"),true);Data.SaveLesson(Path.Combine(folder,"lesson.json"),p);Console.WriteLine("prepared "+p.cues.Count+" cues, "+p.groups.Count+" groups, "+p.duration+" seconds");return;}
  if(args.Length>0&&args[0]=="--normalize"){Lesson p=Data.Load<Lesson>(args[1]);int n=Data.SmoothFragments(p);Data.SaveLesson(args[1],p);Console.WriteLine("merged_fragments="+n);return;}
  if(args.Length>0&&args[0]=="--export"){using(Studio exporter=new Studio(false)){exporter.LoadProject(args[1]);Console.WriteLine(exporter.ExportTo(args[2]));}return;}
  bool player=Path.GetFileNameWithoutExtension(Application.ExecutablePath).Contains("课堂");Studio f=new Studio(player);string file=args.FirstOrDefault(a=>a.EndsWith(".json",StringComparison.OrdinalIgnoreCase));if(file==null){string local=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"lesson.json");if(File.Exists(local))file=local;}if(file!=null){if(args.Length>0&&args[0].StartsWith("--"))f.LoadProject(file);else TryLoadStartup(f,file,message=>MessageBox.Show(message,"材料未打开，可重新选择"));}
  if(args.Length>0&&args[0]=="--render"){f.Rendering=true;f.ShowInTaskbar=false;f.Opacity=0;f.Show();Application.DoEvents();f.PerformLayout();using(Bitmap b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(0,0,b.Width,b.Height));b.Save(args[2]);}f.Dispose();return;}
  Application.Run(f);
 }catch(Exception ex){if(args.Length>0&&args[0].StartsWith("--")){Console.Error.WriteLine(ex);Environment.ExitCode=1;}else MessageBox.Show(ex.Message,"启动未完成");}}
}
}
